/**
 * The app's strings per locale, as the iPhone (and web) get them: the base
 * files generated by scripts/build-i18n.py into mobile/i18n/{locale}.json.
 *
 * On Android, Metro resolves `./resources` to resources.android.ts instead,
 * which adds mobile/i18n/android/{locale}.json: the few strings only Android
 * shows (they name the VPN its shield runs as). Keeping them out of this file
 * keeps them out of the iPhone's bundle — App Review's automated check read
 * the word there as VPN functionality (docs/IOS.md §3.6). Which key goes
 * where: scripts/i18n_mobile.py.
 */
import en from "../../i18n/en.json";
import ru from "../../i18n/ru.json";
import es from "../../i18n/es.json";
import pt from "../../i18n/pt.json";
import fr from "../../i18n/fr.json";
import de from "../../i18n/de.json";
import it from "../../i18n/it.json";
import id from "../../i18n/id.json";
import hi from "../../i18n/hi.json";
import ar from "../../i18n/ar.json";

export const RESOURCES = {
  en: { translation: en },
  ru: { translation: ru },
  es: { translation: es },
  pt: { translation: pt },
  fr: { translation: fr },
  de: { translation: de },
  it: { translation: it },
  id: { translation: id },
  hi: { translation: hi },
  ar: { translation: ar },
};
